import{_ as o,c as t,o as d,ae as i}from"./chunks/framework.CFeneB-q.js";const u=JSON.parse('{"title":"移动端 · 快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/getting-started.md","filePath":"mobile/getting-started.md","lastUpdated":1789438865000}'),r={name:"mobile/getting-started.md"};function a(l,e,n,s,c,p){return d(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="移动端-·-快速开始" tabindex="-1">移动端 · 快速开始 <a class="header-anchor" href="#移动端-·-快速开始" aria-label="Permalink to &quot;移动端 · 快速开始&quot;">​</a></h1><blockquote><p>目标：半天内把 <code>delivery-template-uniapp</code> 跑在微信开发者工具 / Android 真机上，并了解新客户项目的启动四步。</p></blockquote><h2 id="环境前置" tabindex="-1">环境前置 <a class="header-anchor" href="#环境前置" aria-label="Permalink to &quot;环境前置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>要求</th><th>说明</th></tr></thead><tbody><tr><td>HBuilderX</td><td>实际使用 <strong>5.07</strong>（≥ uView 要求的 3.1.0）</td><td>官网下载 App 开发版；本模板是 HBuilderX 工程（非 CLI），所有运行/打包都在 IDE 内</td></tr><tr><td>微信开发者工具</td><td>最新稳定版</td><td>运行小程序必需；需在「安全设置」开启服务端口，HBuilderX 才能拉起</td></tr><tr><td>Android 真机</td><td>Android 8+ 建议</td><td>调试 App 端需要；首次运行允许安装与 USB 调试</td></tr><tr><td>Node.js</td><td>非必需</td><td>HBuilderX 内置编译器；工程无 npm 构建链（package.json 仅为声明残留，见<a href="./technology-stack.html">技术栈</a>）</td></tr></tbody></table><h2 id="跑起来-两步" tabindex="-1">跑起来（两步） <a class="header-anchor" href="#跑起来-两步" aria-label="Permalink to &quot;跑起来（两步）&quot;">​</a></h2><ol><li>HBuilderX → 文件 → 打开目录 → 选择 <code>delivery-template-uniapp</code>；</li><li>运行： <ul><li><strong>小程序</strong>：菜单「运行 → 运行到小程序模拟器 → 微信开发者工具」。首次会要求配置微信开发者工具安装路径；</li><li><strong>App</strong>：手机连 USB（开启开发者模式与 USB 调试）→「运行 → 运行到手机或模拟器 → 运行到 Android App 基座」。标准基座即可跑通；用到自定义原生插件时需制作自定义基座（工程 <code>nativeplugins/</code> 当前仅 google-services.json）。</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">环境切换</p><p>后端环境在 <code>config/index.js</code> 内按平台自动选择：小程序按 <code>envVersion</code>（开发版 → <code>sso.dev01</code>，正式版 → 生产），App 生产指向固定 IP。本地联调想走代理时，可写 <code>uni.setStorageSync(&#39;proxyUrl&#39;, ...)</code> 覆盖 baseURL（<code>utils/request.js</code> 优先读取）。</p></div><h2 id="新项目启动四步-来自现有实践" tabindex="-1">新项目启动四步（来自现有实践） <a class="header-anchor" href="#新项目启动四步-来自现有实践" aria-label="Permalink to &quot;新项目启动四步（来自现有实践）&quot;">​</a></h2><p>新客户项目 = 复制模板 + 四处修改：</p><ol><li><strong>复制</strong> <code>delivery-template-uniapp</code> 整目录为新项目目录（派生关系记录到项目 README，避免出现第二个「权威模板」）；</li><li><strong>改 manifest.json</strong>：<code>name</code>（新客户应用名）、<code>appid</code>（HBuilderX 重新生成，模板值为 <code>__UNI__F0A5577</code>）、<code>mp-weixin.appid</code>（客户的微信小程序 appid）、图标与启动图（源文件放 <code>keystone_public/icon</code>、<code>keystone_public/splash</code>）、Android 包名 <code>app-plus.distribute.android.package</code>（模板值为 <code>uni.app.UNIF0A5577</code>）；</li><li><strong>加 prefix-rules 规则</strong>：在 <code>utils/prefix-rules.js</code> 的 <code>PREFIX_RULES</code> 中为客户增加一条（域名列表 + 前缀 + 需改写的路由；无特殊路由可置空数组，参考 <code>cl</code> 客户）；</li><li><strong>服务端配置</strong>：在运营端为新租户配置菜单树与按钮权限（移动端菜单是运行时下发的，前端无需改动）。</li></ol><h2 id="app-打包与发布" tabindex="-1">App 打包与发布 <a class="header-anchor" href="#app-打包与发布" aria-label="Permalink to &quot;App 打包与发布&quot;">​</a></h2><ul><li><strong>入口</strong>：HBuilderX → 发行 → 原生 App-云打包（常用）/ 本地打包（离线 SDK，历史从 4.7.6 起维护）；</li><li><strong>签名与证书</strong>：<code>keystone_public/签名/</code>（develop / distribution 双环境，iOS 证书在 <code>fanchang_IOS_证书/</code> 子目录）；</li><li><strong>安装包归档</strong>：<code>keystone_public/安装包/</code>（按应用市场分目录：360 / 安智 / 百度 / 苹果 / 应用宝）；</li><li><strong>版本号规则</strong>：<code>manifest.json</code> 的 <code>versionName</code> / <code>versionCode</code> 成对升级，规则如 <code>2.4.2</code> ↔ <code>20402</code>（主/次/补丁 × 10000 换算）；</li><li><strong>上架材料</strong>：截图各尺寸、软著、账号资料集中在 <code>keystone_public/</code>（截图/软著/各平台账号资料/授权文件）。</li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p><code>keystone_public/</code> 已被 .gitignore 忽略且不在 git 仓库内——签名证书与安装包<strong>只存在于本机/归档盘</strong>，换机器前先确认备份。此风险已记入缺口分析（模板仓库化遗留项）。</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>微信开发者工具拉不起来</strong>：检查工具的服务端口是否开启；HBuilderX 配置的安装路径是否正确；</li><li><strong>小程序请求 404 / 域名不合法</strong>：开发阶段在开发者工具勾选「不校验合法域名」；正式域名需在小程序后台配置 request 合法域名；</li><li><strong>App 热更新不生效 / 版本不匹配</strong>：确认打包所用 HBuilderX 版本与线上 wgt 基线一致（README 记载 2.3.10 曾因 sdk 版本不匹配需用 5.07 重打包）；</li><li><strong><code>pnpm dev:mp-weixin</code> 跑不了</strong>：这是工程现状缺陷——<code>dev:mp-weixin</code> 在 package.json 里是顶层键不是脚本，npm 脚本方式不可用，统一走 HBuilderX 运行。</li></ul><hr><p><strong>负责人</strong>：E9 前端团队 ｜ <strong>最后验证日期</strong>：2026-09-16 ｜ <strong>对应蓝本项目</strong>：<code>delivery-template-uniapp</code></p>',17)])])}const h=o(r,[["render",a]]);export{u as __pageData,h as default};
